  json: {
    id: c.id,
    link_ig_2: (ig ? ig.link_ig_2 : c.link_ig_2) || '',
    link_fb_2: (fb ? fb.link_fb_2 : c.link_fb_2) || '',
    pubblicato_il_2: testoRoma(Date.now()),
    errore_2: avvisi.length ? `Pubblicato con avvisi: ${avvisi.join(' · ')}` : '',
    avviso_html: avvisoHtml,
  },
}];

// Qualcosa non è andato sulla seconda coppia. Qui arrivano TUTTI gli errori previsti, già etichettati dal nodo
// prima (un nodo «Errore …» o «… fallita / tempo scaduto»):
//   fase    = prima    → su quella piattaforma della seconda coppia NON è uscito niente
//             incerta  → l'errore è arrivato proprio mentre si pubblicava: potrebbe essere uscito lo stesso
//   origine = nostro   → il motivo l'abbiamo scritto noi (dati, file): può andare su Telegram
//             meta     → il motivo viene da Meta: va SOLO nella colonna errore_2, mai su Telegram (Termini Meta)
//   ambito  = contenuto → problema nei dati della riga o nei file, prima di parlare con Meta
// La riga diventa stato_2 = errore. La prima coppia NON viene toccata: stato, link_ig, link_fb restano come sono.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const e = $input.first().json || {};
const c = $('Prepara contenuto').first().json;
const fase = e.fase === 'incerta' ? 'incerta' : 'prima';
const origine = e.origine === 'nostro' ? 'nostro' : 'meta';

function messaggi(x, profondita = 0, raccolti = []) {
  if (typeof x === 'string') { if (x.trim()) raccolti.push(x.trim()); return raccolti; }
  if (!x || typeof x !== 'object' || profondita > 4) return raccolti;
  for (const k of ['message', 'description']) if (typeof x[k] === 'string' && x[k].trim()) raccolti.push(x[k].trim());
  if (!raccolti.length) for (const v of Object.values(x)) messaggi(v, profondita + 1, raccolti);
  return raccolti;
}
const dettaglio = String(e.problema || '').trim()
  || [...new Set(messaggi(e.error))].join(' — ')
  || 'errore senza messaggio';

// Quale piattaforma? Instagram si fa prima: se era da fare e il suo link non è stato salvato, l'errore è lì.
const igFatto = !c.pubblica_ig || $('Salva link Instagram provvisorio').isExecuted;
const piattaforma = !igFatto ? 'Instagram' : 'Facebook';
const datiOFile = e.ambito === 'contenuto'; // dati della riga o file: vale per tutta la seconda coppia
const dove = datiOFile ? 'Seconda coppia' : `${piattaforma} della seconda coppia`;

const cosaFare = fase === 'incerta'
  ? `Prima di riprovare guarda su ${piattaforma} della seconda coppia se è uscito lo stesso: se sì incolla il link in ${piattaforma === 'Instagram' ? 'link_ig_2' : 'link_fb_2'} e scrivi pubblicato in stato_2; se no scrivi approvato in stato_2 (non in stato).`
  : 'Sistema, poi scrivi approvato in stato_2 (non in stato): rifaccio solo quello che manca sulla seconda coppia.';
const giaUscito = c.pubblica_ig && igFatto && piattaforma === 'Facebook' ? ' Instagram della seconda coppia invece è uscito (link_ig_2 pieno): non verrà ripubblicato.' : '';
const errore2 = `${dove}: ${dettaglio.slice(0, 450)}.${giaUscito} ${cosaFare}`.replace(/\.\./g, '.');

const righeTelegram = [
  `⚠️ <b>${esc(c.nome_locale)}</b> · id ${esc(c.id)} (${esc(c.tipo || '?')}, riga ${esc(c.row_number)})`,
  `${esc(dove)}: ${fase === 'incerta' ? 'errore mentre pubblicavo, <b>potrebbe essere uscito lo stesso</b>' : 'non pubblicato'}.`,
];
if (origine === 'nostro') righeTelegram.push(`Motivo: ${esc(dettaglio.slice(0, 600))}`);
else righeTelegram.push("Meta ha restituito un errore: il testo completo non lo riporto qui, è nella colonna errore_2 del Calendario.");
if (giaUscito) righeTelegram.push(esc(giaUscito.trim()));
righeTelegram.push(esc(cosaFare));
righeTelegram.push('La prima coppia non è stata toccata.');

return [{ json: { id: c.id, stato_2: 'errore', errore_2: errore2, avviso_html: righeTelegram.join('\n') } }];
